import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './History.css';

/* ──────────────────────────────────────────────────────────
   SEASON DATA — single source of truth
────────────────────────────────────────────────────────── */
const SEASONS = [
  {
    id:    'decode',
    year:  '2025',
    game:  'Decode',
    robot: 'Pegasus',
    tag:   'current',
    label: 'Decode 2025',
    type:  'completed',
    sub:   'East Bay League · Dublin, CA · FTC Division',
    intro:
      'Our team competed in the Decode season with Pegasus, our first competition robot. ' +
      'Built on precision OnShape CAD and a refined Java + Pedro Pathing software architecture, ' +
      'Pegasus powered us through four events and earned a Connect Award at the League Tournament.',
    stats: [
      { val: '4',  label: 'Events Competed' },
      { val: '20', label: 'Matches Played' },
      { val: 'Top 10', label: 'Tournament Rank' },
      { val: '1',  label: 'Award Won' },
    ],
    award: {
      icon:  '🏆',
      name:  'Connect Award',
      event: 'East Bay League Tournament',
      desc:
        'The FIRST Tech Challenge Connect Award recognizes teams that best exemplify the ' +
        'FIRST mission — inspiring others to pursue STEM through advocacy, partnerships, and ' +
        'outreach. Winning this in our rookie season reflects our commitment to community ' +
        'impact, from founding BASE Robotics to hosting free workshops across the Tri-Valley.',
      stats: [
        { val: '2',    label: 'Nonprofits Founded / Joined' },
        { val: '100+', label: 'Students Reached' },
        { val: '4',    label: 'FTC Teams Assisted' },
      ],
    },
    events: [
      {
        id:        'meet-1',
        name:      'East Bay League — Meet 1',
        date:      'Oct 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'completed',
        badge:     'debut',
        highlight: false,
        detail:
          'Pegasus took the field for the first time. We stress-tested our autonomous routines ' +
          'in a live match environment and gathered critical performance data to drive our next ' +
          'round of mechanical and software refinements.',
      },
      {
        id:        'meet-2',
        name:      'East Bay League — Meet 2',
        date:      'Nov 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'completed',
        badge:     'competed',
        highlight: false,
        detail:
          'Armed with Match 1 footage and field data, Pegasus returned with hardware and ' +
          'software improvements — a better autonomous cycle count and tighter driver coordination ' +
          'through refined Pedro Pathing trajectories.',
      },
      {
        id:        'meet-3',
        name:      'East Bay League — Meet 3',
        date:      'Dec 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'completed',
        badge:     'competed',
        highlight: false,
        detail:
          'Our most polished regular-season outing. Pegasus\'s autonomous reliability reached ' +
          'a new high-water mark and alliance strategies showed measurable improvement heading ' +
          'into the League Tournament.',
      },
      {
        id:        'tournament',
        name:      'East Bay League Tournament',
        date:      'Jan 2025',
        venue:     'East Bay Region, CA',
        result:    '🏆 Connect Award',
        status:    'award',
        badge:     'award',
        highlight: true,
        detail:
          'Pegasus placed in the Top 10 with 20 successful matches across 4 competitions, ' +
          'powered by our Pinpoint odometry and Pedro Pathing architecture. We were selected as ' +
          'the 1st pick of the 3rd Alliance, bringing reliable Java autonomous routines and ' +
          'consistent teleop scoring to the playoffs. We finished as the 4th place alliance ' +
          'overall and proudly took home the Connect Award.',
      },
    ],
  },
  {
    id:    'biobuzz',
    year:  '2026',
    game:  'BIOBUZZ',
    robot: 'TBD',
    tag:   'upcoming',
    label: 'BIOBUZZ 2026',
    type:  'upcoming',
    sub:   'East Bay League · Dublin, CA · FTC Division',
    intro:
      'We are preparing for our first official matches of the BIOBUZZ season. ' +
      'Hardware is in development, software is being refined, and the team is ready ' +
      'to compete at a higher level than ever before.',
    stats: [
      { val: '4',  label: 'Events Scheduled' },
      { val: '—',  label: 'Matches Played' },
      { val: '—',  label: 'Current Rank' },
      { val: '—',  label: 'Awards' },
    ],
    events: [
      {
        id:     'biobuzz-meet-1',
        name:   'East Bay League — Meet 1',
        date:   'Fall 2025',
        venue:  'East Bay Region, CA',
        result: 'Upcoming',
        status: 'upcoming',
        badge:  'upcoming',
        highlight: false,
        detail:
          'Our first official match of the BIOBUZZ season. Hardware and software ' +
          'development is underway as we adapt to the new game challenge.',
      },
      {
        id:     'biobuzz-meet-2',
        name:   'East Bay League — Meet 2',
        date:   'Winter 2025',
        venue:  'East Bay Region, CA',
        result: 'Upcoming',
        status: 'upcoming',
        badge:  'upcoming',
        highlight: false,
        detail:
          'Building on Meet 1 data, we plan to deploy fully refined autonomous routines ' +
          'and competition-hardened scoring mechanisms.',
      },
      {
        id:     'biobuzz-meet-3',
        name:   'East Bay League — Meet 3',
        date:   'Winter 2025',
        venue:  'East Bay Region, CA',
        result: 'Upcoming',
        status: 'upcoming',
        badge:  'upcoming',
        highlight: false,
        detail:
          'Our most polished regular-season outing of the BIOBUZZ campaign. With three ' +
          'meets of field data behind us, we push Pedro Pathing trajectory accuracy and ' +
          'teleop execution to their limits ahead of the League Tournament.',
      },
      {
        id:     'biobuzz-tournament',
        name:   'East Bay League Tournament',
        date:   'Early 2026',
        venue:  'East Bay Region, CA',
        result: 'Upcoming',
        status: 'upcoming',
        badge:  'upcoming',
        highlight: false,
        detail:
          'Our second appearance at the League Tournament — the first chance to defend the ' +
          'standard set in our rookie year and push for new hardware and software milestones.',
      },
    ],
  },
];

/* ──────────────────────────────────────────────────────────
   SEASON PILL
────────────────────────────────────────────────────────── */
function SeasonPill({ tag }) {
  if (!tag) return null;
  const labels = { current: 'Current Season', upcoming: 'Upcoming', completed: 'Completed' };
  return (
    <span className={`season-pill season-pill--${tag}`}>
      {labels[tag] ?? tag}
    </span>
  );
}

/* ──────────────────────────────────────────────────────────
   SEASON DROPDOWN
────────────────────────────────────────────────────────── */
function SeasonDropdown({ seasons, selected, onSelect }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const close = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, []);

  useEffect(() => {
    const esc = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('keydown', esc);
    return () => document.removeEventListener('keydown', esc);
  }, []);

  const current = seasons.find((s) => s.id === selected);

  return (
    <div className={`season-dropdown ${open ? 'season-dropdown--open' : ''}`} ref={ref}>
      <button
        id="season-dropdown-trigger"
        className="season-dropdown__trigger"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label="Select competition season"
      >
        <span className="season-dropdown__trigger-left">
          <span className="season-dropdown__trigger-label">Season</span>
          <span className="season-dropdown__trigger-value">
            {current?.label}
            {current?.tag && <SeasonPill tag={current.tag} />}
          </span>
        </span>
        <span className="season-dropdown__chevron" aria-hidden="true">
          {open ? '▲' : '▼'}
        </span>
      </button>

      <ul className="season-dropdown__menu" role="listbox" aria-label="Competition seasons">
        {seasons.map((season) => (
          <li
            key={season.id}
            role="option"
            aria-selected={season.id === selected}
            className={`season-dropdown__option ${season.id === selected ? 'season-dropdown__option--active' : ''}`}
            onClick={() => { onSelect(season.id); setOpen(false); }}
            id={`season-option-${season.id}`}
          >
            <span className="season-dropdown__option-meta">
              <span className="season-dropdown__option-game">{season.label}</span>
              <span className="season-dropdown__option-sub">{season.robot !== 'TBD' ? `Robot: ${season.robot}` : 'Robot: TBD'}</span>
            </span>
            {season.tag && <SeasonPill tag={season.tag} />}
            {season.id === selected && (
              <span className="season-dropdown__check" aria-hidden="true">✓</span>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   SEASON STATS BAR
────────────────────────────────────────────────────────── */
function SeasonStatsBar({ stats }) {
  return (
    <div className="season-stats-bar">
      {stats.map(({ val, label }) => (
        <div key={label} className="season-stats-bar__item">
          <span className="season-stats-bar__val">{val}</span>
          <span className="season-stats-bar__label">{label}</span>
        </div>
      ))}
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   EVENT FEED WIDGET
────────────────────────────────────────────────────────── */
function EventWidget({ event, robot }) {
  const statusMeta = {
    award:     { label: '🏆 Award',    cls: 'award'     },
    completed: { label: 'Completed',   cls: 'completed'  },
    upcoming:  { label: 'Upcoming',    cls: 'upcoming'   },
    debut:     { label: 'Debut',       cls: 'debut'      },
    competed:  { label: 'Competed',    cls: 'competed'   },
  };
  const meta = statusMeta[event.badge] ?? statusMeta[event.status] ?? { label: 'Event', cls: 'competed' };

  return (
    <div
      id={event.id}
      className={`event-widget ${event.highlight ? 'event-widget--award' : ''}`}
    >
      {/* Left accent bar (yellow on award) */}
      <div className="event-widget__accent" aria-hidden="true" />

      <div className="event-widget__body">
        {/* Top row: title + status + date */}
        <div className="event-widget__top">
          <div className="event-widget__title-group">
            <h3 className="event-widget__name">{event.name}</h3>
            <span className="event-widget__venue">📍 {event.venue}</span>
          </div>
          <div className="event-widget__right">
            <span className={`event-widget__status event-widget__status--${meta.cls}`}>
              {meta.label}
            </span>
            <span className="event-widget__date">{event.date}</span>
          </div>
        </div>

        {/* Detail paragraph */}
        <p className="event-widget__detail">
          {event.badge === 'debut' || event.badge === 'competed' || event.badge === 'award' ? (
            /* Inject robot name as yellow span on first mention */
            (() => {
              const text = event.detail;
              const idx  = text.indexOf(robot);
              if (idx === -1 || !robot || robot === 'TBD') return text;
              return (
                <>
                  {text.slice(0, idx)}
                  <span className="text-yellow font-semibold">{robot}</span>
                  {text.slice(idx + robot.length)}
                </>
              );
            })()
          ) : event.detail}
        </p>

        {/* Result chip */}
        {event.result && event.status !== 'upcoming' && (
          <div className="event-widget__result-row">
            <span className={`event-widget__result ${event.highlight ? 'event-widget__result--award' : ''}`}>
              {event.result}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   CONNECT AWARD FEATURE BLOCK
────────────────────────────────────────────────────────── */
function ConnectAwardBlock({ award, game }) {
  return (
    <div className="connect-award" id="connect-award" aria-label="Award detail">
      <div className="connect-award__glow" aria-hidden="true" />
      <div className="connect-award__inner">
        <div className="connect-award__left">
          <span className="connect-award__icon" aria-hidden="true">{award.icon}</span>
          <div>
            <p className="label-tag connect-award__tag">Highest Achievement — {game}</p>
            <h3 className="headline headline-md connect-award__title">
              {award.name} <span className="text-yellow">Winner</span>
            </h3>
          </div>
        </div>
        <p className="connect-award__desc">{award.desc}</p>
        <div className="connect-award__stats">
          {award.stats.map(({ val, label }) => (
            <div key={label} className="connect-award__stat">
              <span className="connect-award__stat-val">{val}</span>
              <span className="connect-award__stat-label">{label}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   TOURNAMENT MONTAGE
────────────────────────────────────────────────────────── */
const matchStats = [
  { label: 'Matches Played',   value: '20' },
  { label: 'Events Competed',  value: '4'  },
  { label: 'Alliance Pick',    value: '1st Pick · 3rd Alliance' },
  { label: 'Final Rank',       value: '4th Place Alliance' },
  { label: 'Awards Won',       value: '1 (Connect Award)' },
];

function TournamentMontage() {
  return (
    <div className="montage" id="tournament-montage" aria-label="Tournament montage">
      <div className="montage__header">
        <div className="section-label">
          <span className="label-tag">Pegasus — East Bay League Tournament</span>
        </div>
        <h3 className="headline headline-md montage__title">
          Tournament <span className="text-yellow">Recap & Montage</span>
        </h3>
        <p className="montage__sub text-muted">
          Our season highlight reel featuring Pegasus in action — full match footage,
          autonomous runs, and alliance playoff moments. Video is currently in post-production.
        </p>
      </div>

      <div className="montage__main">
        {/* Video player */}
        <div className="montage__player-wrap">
          <iframe
            id="montage-iframe"
            className="montage__iframe"
            src="https://www.youtube.com/embed/dQw4w9WgXcQ"
            title="Team Duck 30473 — East Bay League Tournament Montage"
            frameBorder="0"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowFullScreen
          />
          <div className="montage__badge">
            <span className="montage__badge-dot" />
            Editing in Progress
          </div>
        </div>

        {/* Match stats sidebar */}
        <aside className="montage__stats" aria-label="Match statistics">
          <p className="label-tag montage__stats-label">Pegasus — Season Stats</p>
          <div className="montage__stats-list">
            {matchStats.map(({ label, value }) => (
              <div key={label} className="montage__stat-row">
                <span className="montage__stat-label">{label}</span>
                <span className="montage__stat-value">{value}</span>
              </div>
            ))}
          </div>
        </aside>
      </div>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   COMPLETED SEASON PANEL
────────────────────────────────────────────────────────── */
function CompletedSeason({ season }) {
  return (
    <div className="season-panel">
      {season.id === 'decode' && <TournamentMontage />}

      {/* Award callout banner */}
      {season.award && (
        <div className="award-banner" aria-label="Season award">
          <span className="award-banner__icon" aria-hidden="true">{season.award.icon}</span>
          <div>
            <span className="award-banner__name">{season.award.name}</span>
            <span className="award-banner__event label-tag">{season.award.event}</span>
          </div>
        </div>
      )}

      {/* Event feed */}
      <div className="event-feed" role="list" aria-label={`${season.game} event feed`}>
        <p className="event-feed__label label-tag">Event Feed</p>
        {season.events.map((event) => (
          <EventWidget key={event.id} event={event} robot={season.robot} />
        ))}
      </div>

      {/* Connect Award Feature */}
      {season.award && (
        <ConnectAwardBlock award={season.award} game={season.game} />
      )}
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   UPCOMING SEASON PANEL
────────────────────────────────────────────────────────── */
function UpcomingSeason({ season }) {
  return (
    <div className="season-panel">
      <div className="upcoming-notice">
        <span className="upcoming-notice__dot" aria-hidden="true" />
        <p className="upcoming-notice__text">
          This season is in preparation. Check back after events conclude for results and recaps.
        </p>
        <Link to="/" className="btn btn-outline btn--sm" id="history-cta-home">← Home</Link>
      </div>

      <div className="event-feed" role="list" aria-label={`${season.game} event feed`}>
        <p className="event-feed__label label-tag">Scheduled Events</p>
        {season.events.map((event) => (
          <EventWidget key={event.id} event={event} robot={season.robot} />
        ))}
      </div>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   PAGE EXPORT — Dashboard layout
────────────────────────────────────────────────────────── */
export default function History() {
  const [selectedId, setSelectedId] = useState('decode');
  const activeSeason = SEASONS.find((s) => s.id === selectedId);

  return (
    <main className="page" id="history-page">

      {/* ── Page Hero ── */}
      <section className="history-hero" aria-labelledby="history-heading">
        <div className="history-hero__bg"   aria-hidden="true" />
        <div className="history-hero__grid" aria-hidden="true" />

        <div className="container history-hero__content">
          <div className="section-label">
            <span className="label-tag">30473 / Season Record</span>
          </div>
          <h1 id="history-heading" className="headline headline-lg history-hero__title">
            Competition <span className="text-yellow">History</span>
          </h1>
          <p className="history-hero__sub text-muted">
            Every match. Every award. Every lesson learned on the field.
            This is how <span className="text-yellow">Pegasus</span> and Team 30473 earn their stripes.
          </p>

          {/* Career highlights strip */}
          <div className="history-hero__highlights">
            {[
              { val: '1',       key: 'Award Won'       },
              { val: '4',       key: 'Meets Competed'  },
              { val: '2025',    key: 'Rookie Year'      },
              { val: 'Decode',  key: 'Current Season'  },
            ].map(({ val, key }) => (
              <div key={key} className="history-hero__highlight">
                <span className="history-hero__highlight-val">{val}</span>
                <span className="history-hero__highlight-key">{key}</span>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── Dashboard ── */}
      <section className="history-dashboard section" aria-label="Season dashboard">
        <div className="container">

          {/* ─── Control Panel ─── */}
          <div className="dashboard__control-panel">

            {/* Left: dropdown */}
            <SeasonDropdown
              seasons={SEASONS}
              selected={selectedId}
              onSelect={setSelectedId}
            />

            {/* Right: active season header */}
            <div className="dashboard__season-header">
              <div className="dashboard__season-title-row">
                <div>
                  <div className="section-label" style={{ marginBottom: '0.3rem' }}>
                    <span className="label-tag">Season Record</span>
                  </div>
                  <h2 className="headline headline-lg dashboard__season-title">
                    {activeSeason.game}{' '}
                    <span className="text-yellow">{activeSeason.year}</span>
                  </h2>
                  <p className="dashboard__season-sub text-muted">{activeSeason.sub}</p>
                </div>
                <div className="dashboard__season-badges">
                  {activeSeason.tag && <SeasonPill tag={activeSeason.tag} />}
                  {activeSeason.robot && activeSeason.robot !== 'TBD' && (
                    <span className="robot-pill">
                      🤖 <span className="text-yellow">{activeSeason.robot}</span>
                    </span>
                  )}
                </div>
              </div>
              <p className="dashboard__season-intro">{activeSeason.intro}</p>
            </div>
          </div>

          {/* ─── Stats Bar ─── */}
          <SeasonStatsBar stats={activeSeason.stats} />

          {/* ─── Panel Content ─── */}
          <div className="dashboard__panel" key={selectedId}>
            {activeSeason.type === 'completed' ? (
              <CompletedSeason season={activeSeason} />
            ) : (
              <UpcomingSeason season={activeSeason} />
            )}
          </div>

        </div>
      </section>

    </main>
  );
}
